package risk

type Config struct {
	TicketThreshold int    `toml:"ticket_threshold"`
	CUSTXPattern    string `toml:"custx_pattern"`
	OffHoursStart   int    `toml:"off_hours_start"`
	OffHoursEnd     int    `toml:"off_hours_end"`
	Timezone        string `toml:"timezone"`

	// EscalationAnnotation is the Teleport system annotation key that marks
	// an access request as a session escalation. A request is treated as an
	// escalation when this key is present with any non-empty value.
	EscalationAnnotation string `toml:"escalation_annotation"`
	// EscalationThreshold is the fallback ticket threshold applied to
	// escalation-flavored requests when no role-specific override matches.
	EscalationThreshold int `toml:"escalation_threshold"`
	// EscalationThresholds overrides EscalationThreshold for specific
	// requested roles. The strictest (lowest) matching value wins when a
	// request names multiple roles.
	EscalationThresholds map[string]int `toml:"escalation_thresholds"`
}

func (c *Config) ApplyDefaults() {
	if c.TicketThreshold == 0 {
		c.TicketThreshold = 25
	}
	if c.CUSTXPattern == "" {
		c.CUSTXPattern = `CUSTX-\d+`
	}
	if c.Timezone == "" {
		c.Timezone = "UTC"
	}
	if c.EscalationAnnotation == "" {
		c.EscalationAnnotation = "ruth.escalation"
	}
	if c.EscalationThreshold == 0 {
		c.EscalationThreshold = 15
	}
}

// EscalationThresholdFor returns the strictest ticket threshold among the
// requested roles. A role without an explicit override uses the global
// EscalationThreshold. An empty role list also yields the global default.
func (c Config) EscalationThresholdFor(roles []string) int {
	if len(roles) == 0 {
		return c.EscalationThreshold
	}
	chosen := -1
	for _, role := range roles {
		t, ok := c.EscalationThresholds[role]
		if !ok {
			t = c.EscalationThreshold
		}
		if chosen == -1 || t < chosen {
			chosen = t
		}
	}
	return chosen
}

type Tier struct {
	Name     string
	MinScore int
}

var Tiers = []Tier{
	{Name: "low", MinScore: 0},
	{Name: "medium", MinScore: 25},
	{Name: "high", MinScore: 50},
	{Name: "critical", MinScore: 75},
}

func TierForScore(score int) Tier {
	chosen := Tiers[0]
	for _, t := range Tiers {
		if score >= t.MinScore {
			chosen = t
		}
	}
	return chosen
}

// Package telemetry wires an OpenTelemetry MeterProvider to an OTLP/gRPC
// collector and publishes per-user reputation as an observable gauge. The
// collector is expected to fan out to Datadog (or any other backend) via
// its own exporter pipeline.
package telemetry

import (
	"context"
	"fmt"
	"time"

	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/exporters/otlp/otlpmetric/otlpmetricgrpc"
	"go.opentelemetry.io/otel/metric"
	sdkmetric "go.opentelemetry.io/otel/sdk/metric"
	"go.opentelemetry.io/otel/sdk/resource"
	semconv "go.opentelemetry.io/otel/semconv/v1.24.0"
)

type Config struct {
	Enabled      bool          `toml:"enabled"`
	Endpoint     string        `toml:"endpoint"`
	Insecure     bool          `toml:"insecure"`
	ServiceName  string        `toml:"service_name"`
	ExportPeriod time.Duration `toml:"export_period"`

	// ShutdownGrace is the delay between receiving SIGINT/SIGTERM and
	// cancelling the watcher/poller context. It gives the OTel periodic
	// reader time to finish an in-flight export before the app tears
	// down; without it shutdowns emit a spurious "context canceled"
	// error from the exporter. Set to 0 to disable.
	ShutdownGrace time.Duration `toml:"shutdown_grace"`
}

func (c *Config) ApplyDefaults() {
	if c.ServiceName == "" {
		c.ServiceName = "ruth"
	}
	if c.ExportPeriod == 0 {
		c.ExportPeriod = 15 * time.Second
	}
	if c.ShutdownGrace == 0 {
		c.ShutdownGrace = 2 * time.Second
	}
}

// ReputationSource is the minimum surface telemetry needs from the
// reputation store: iterate the users it currently knows about.
type ReputationSource interface {
	Range(fn func(user string, score int))
}

type Meter struct {
	provider *sdkmetric.MeterProvider
	reg      metric.Registration
}

func New(ctx context.Context, cfg Config, src ReputationSource) (*Meter, error) {
	opts := []otlpmetricgrpc.Option{}
	if cfg.Endpoint != "" {
		opts = append(opts, otlpmetricgrpc.WithEndpoint(cfg.Endpoint))
	}
	if cfg.Insecure {
		opts = append(opts, otlpmetricgrpc.WithInsecure())
	}
	exp, err := otlpmetricgrpc.New(ctx, opts...)
	if err != nil {
		return nil, fmt.Errorf("otlp exporter: %w", err)
	}

	res, err := resource.New(ctx, resource.WithAttributes(semconv.ServiceName(cfg.ServiceName)))
	if err != nil {
		return nil, fmt.Errorf("resource: %w", err)
	}

	provider := sdkmetric.NewMeterProvider(
		sdkmetric.WithResource(res),
		sdkmetric.WithReader(sdkmetric.NewPeriodicReader(exp, sdkmetric.WithInterval(cfg.ExportPeriod))),
	)
	otel.SetMeterProvider(provider)

	meter := provider.Meter("ruth/reputation")
	gauge, err := meter.Int64ObservableGauge(
		"ruth.user.reputation",
		metric.WithDescription("Per-user reputation score (lower = worse)"),
	)
	if err != nil {
		_ = provider.Shutdown(ctx)
		return nil, fmt.Errorf("register gauge: %w", err)
	}

	reg, err := meter.RegisterCallback(func(_ context.Context, o metric.Observer) error {
		src.Range(func(user string, score int) {
			o.ObserveInt64(gauge, int64(score), metric.WithAttributes(
				attribute.String("user", user),
			))
		})
		return nil
	}, gauge)
	if err != nil {
		_ = provider.Shutdown(ctx)
		return nil, fmt.Errorf("register callback: %w", err)
	}

	return &Meter{provider: provider, reg: reg}, nil
}

// Shutdown unregisters the callback and flushes pending metrics to the
// collector. Safe to call on a nil receiver.
func (m *Meter) Shutdown(ctx context.Context) error {
	if m == nil || m.provider == nil {
		return nil
	}
	_ = m.reg.Unregister()
	return m.provider.Shutdown(ctx)
}
